update public.questions set options = '[{"body": "had the support of a Portuguese fleet that cut off the supplies of the Mughal armies by sea", "body_hi": "पुर्तगाली बेड़े का समर्थन पाया, जिसने समुद्र के रास्ते मुग़ल सेनाओं की रसद काट दी", "id": "a", "isCorrect": false}, {"body": "made an alliance with the Safavid Shah of Persia, who sent an army to help him in the Deccan", "body_hi": "फ़ारस के सफ़वी शाह से गठबंधन किया, जिसने उसकी सहायता के लिए दक्कन में अपनी एक सेना भेजी", "id": "b", "isCorrect": false}, {"body": "used Maratha light cavalry for guerrilla war and won the peasants with a fair revenue system", "body_hi": "मराठा हल्के घुड़सवारों से छापामार युद्ध किया और उचित राजस्व व्यवस्था से किसानों को जीता", "id": "c", "isCorrect": true}, {"body": "built a chain of forts manned by European gunners across the Deccan", "body_hi": "पूरे दक्कन में ऐसे क़िलों की शृंखला बनाई जिनमें यूरोपीय तोपची तैनात थे", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '2b52ca81-a346-4565-a6f6-d175fb3cf593' and options = '[{"body": "had the support of a Portuguese fleet that cut off the supplies of the Mughal armies by sea", "body_hi": "पुर्तगाली बेड़े का समर्थन पाया जिसने समुद्र से मुग़ल सेनाओं की रसद काट दी", "id": "a", "isCorrect": false}, {"body": "made an alliance with the Safavid Shah of Persia, who sent an army to help him in the Deccan", "body_hi": "फ़ारस के सफ़वी शाह से गठबंधन किया, जिसने दक्कन में सेना भेजी", "id": "b", "isCorrect": false}, {"body": "used Maratha light cavalry for guerrilla war and won the peasants with a fair revenue system", "body_hi": "मराठा हल्की घुड़सवार सेना से छापामार युद्ध किया और न्यायसंगत राजस्व व्यवस्था से किसानों को अपने साथ रखा", "id": "c", "isCorrect": true}, {"body": "built a chain of forts manned by European gunners across the Deccan", "body_hi": "पूरे दक्कन में यूरोपीय तोपचियों वाले क़िलों की शृंखला बनाई", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "capital expenditure minus the loans and advances given to the States", "body_hi": "पूँजीगत व्यय में से राज्यों को दिए गए ऋणों और अग्रिमों को घटाकर प्राप्त राशि", "id": "a", "isCorrect": false}, {"body": "capital expenditure plus the proceeds of disinvestment received in the year", "body_hi": "पूँजीगत व्यय और उसी वर्ष में प्राप्त विनिवेश आय का योग", "id": "b", "isCorrect": false}, {"body": "capital expenditure of the Centre and the States taken together as one", "body_hi": "केंद्र और राज्यों का पूँजीगत व्यय एक साथ मिलाकर", "id": "c", "isCorrect": false}, {"body": "capital expenditure plus grants-in-aid for the creation of capital assets", "body_hi": "पूँजीगत व्यय और पूँजीगत परिसंपत्तियों के सृजन हेतु सहायता अनुदान का योग", "id": "d", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '1fe953c0-0b6f-4651-8fbb-2c70521a818e' and options = '[{"body": "capital expenditure minus the loans and advances given to the States", "body_hi": "पूँजीगत व्यय में से राज्यों को दिए गए ऋण और अग्रिम घटाकर", "id": "a", "isCorrect": false}, {"body": "capital expenditure plus the proceeds of disinvestment received in the year", "body_hi": "पूँजीगत व्यय और वर्ष में प्राप्त विनिवेश आय का योग", "id": "b", "isCorrect": false}, {"body": "capital expenditure of the Centre and the States taken together as one", "body_hi": "केंद्र और राज्यों का पूँजीगत व्यय एक साथ मिलाकर", "id": "c", "isCorrect": false}, {"body": "capital expenditure plus grants-in-aid for the creation of capital assets", "body_hi": "पूँजीगत व्यय और पूँजीगत परिसंपत्तियों के सृजन के लिए सहायता अनुदान का योग", "id": "d", "isCorrect": true}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "had by then made the Portuguese their main allies in the war against the Dutch", "body_hi": "तब तक डचों के विरुद्ध युद्ध में पुर्तगालियों को ही अपना मुख्य सहयोगी बना चुके थे", "id": "a", "isCorrect": false}, {"body": "expelled all the European trading companies from Bengal for the rest of the seventeenth century", "body_hi": "ने सत्रहवीं शताब्दी के शेष भाग के लिए सभी यूरोपीय व्यापारिक कंपनियों को बंगाल से बाहर निकाल दिया", "id": "b", "isCorrect": false}, {"body": "had begun to build a large navy in order to drive the Portuguese out of Goa", "body_hi": "ने गोवा से पुर्तगालियों को बाहर निकालने के लिए एक बड़ी नौसेना का निर्माण शुरू कर दिया था", "id": "c", "isCorrect": false}, {"body": "could act decisively against Europeans on land, though they had no navy to match them at sea", "body_hi": "थल पर यूरोपीयों पर निर्णायक कार्रवाई कर सकते थे, यद्यपि समुद्र में उनकी बराबरी की नौसेना न थी", "id": "d", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = 'd9f59deb-8290-4119-8a13-ed44cda08e5c' and options = '[{"body": "had by then made the Portuguese their main allies in the war against the Dutch", "body_hi": "तब तक पुर्तगालियों को डचों के विरुद्ध युद्ध में अपना मुख्य सहयोगी बना चुके थे", "id": "a", "isCorrect": false}, {"body": "expelled all the European trading companies from Bengal for the rest of the seventeenth century", "body_hi": "ने सत्रहवीं सदी के शेष भाग के लिए बंगाल से सभी यूरोपीय व्यापारियों को निकाल दिया", "id": "b", "isCorrect": false}, {"body": "had begun to build a large navy in order to drive the Portuguese out of Goa", "body_hi": "ने पुर्तगालियों को गोवा से निकालने के लिए एक बड़ी नौसेना बनानी शुरू कर दी थी", "id": "c", "isCorrect": false}, {"body": "could act decisively against Europeans on land, though they had no navy to match them at sea", "body_hi": "स्थल पर यूरोपीयों के विरुद्ध निर्णायक कार्रवाई कर सकते थे, यद्यपि समुद्र में उनसे टक्कर लेने वाली नौसेना उनके पास नहीं थी", "id": "d", "isCorrect": true}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "is the oldest surviving form of Kathakali, from which the masks and make-up of Kathakali developed", "body_hi": "कथकली का सबसे पुराना जीवित रूप है, जिससे आगे चलकर कथकली के मुखौटे और रंग-सज्जा विकसित हुए", "id": "a", "isCorrect": false}, {"body": "is performed in Tamil by village troupes in open squares during the harvest festival", "body_hi": "फ़सल के त्योहार के समय खुले चौकों में गाँव की नाट्य-मंडलियों द्वारा तमिल भाषा में खेला जाता है", "id": "b", "isCorrect": false}, {"body": "keeps Sanskrit drama alive on stage in Kerala''s temple theatres, with women in the female roles", "body_hi": "केरल के मंदिर-रंगमंचों में संस्कृत नाटक जीवित रखता है; इसमें स्त्री-पात्र स्त्रियाँ निभाती हैं", "id": "c", "isCorrect": true}, {"body": "is a shadow-puppet theatre that tells the Ramayana with leather figures", "body_hi": "चमड़े की आकृतियों से रामायण कहने वाला छाया-कठपुतली रंगमंच है", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = 'af41169d-c502-4f71-a98a-dfbe4a54d52b' and options = '[{"body": "is the oldest surviving form of Kathakali, from which the masks and make-up of Kathakali developed", "body_hi": "कथकली का सबसे पुराना बचा रूप है, जिससे कथकली के मुखौटे और रंग-सज्जा विकसित हुए", "id": "a", "isCorrect": false}, {"body": "is performed in Tamil by village troupes in open squares during the harvest festival", "body_hi": "फ़सल के त्योहार पर खुले चौकों में गाँव की मंडलियों द्वारा तमिल में खेला जाता है", "id": "b", "isCorrect": false}, {"body": "keeps Sanskrit drama alive on stage in Kerala''s temple theatres, with women in the female roles", "body_hi": "केरल के मंदिर-रंगमंचों में संस्कृत नाटक को मंच पर जीवित रखता है, जिसमें स्त्री-भूमिकाएँ स्त्रियाँ निभाती हैं", "id": "c", "isCorrect": true}, {"body": "is a shadow-puppet theatre that tells the Ramayana with leather figures", "body_hi": "चमड़े की आकृतियों से रामायण कहने वाला छाया-कठपुतली रंगमंच है", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
