update public.questions set options = '[{"body": "the exact order and dates of succession of the kings of Magadha", "body_hi": "मगध के राजाओं के उत्तराधिकार के ठीक-ठीक क्रम और उनकी सही तिथियों का", "id": "a", "isCorrect": false}, {"body": "the teachings of the Jain Tirthankaras and the rules of Jain monks", "body_hi": "जैन तीर्थंकरों की शिक्षाओं और जैन भिक्षुओं के नियमों का", "id": "b", "isCorrect": false}, {"body": "the rules for performing the great Vedic sacrifices such as the ashvamedha", "body_hi": "अश्वमेध जैसे बड़े वैदिक यज्ञों को संपन्न करने के विधि-नियमों का", "id": "c", "isCorrect": false}, {"body": "social and economic life in their times -- trade, crafts and guilds", "body_hi": "अपने युग के सामाजिक-आर्थिक जीवन का -- व्यापार, शिल्प, श्रेणियाँ", "id": "d", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = 'da896f99-e906-48dd-aee7-cb6f8c2ceef8' and options = '[{"body": "the exact order and dates of succession of the kings of Magadha", "body_hi": "मगध के राजाओं के उत्तराधिकार के सटीक क्रम और तिथियों का", "id": "a", "isCorrect": false}, {"body": "the teachings of the Jain Tirthankaras and the rules of Jain monks", "body_hi": "जैन तीर्थंकरों की शिक्षाओं और जैन भिक्षुओं के नियमों का", "id": "b", "isCorrect": false}, {"body": "the rules for performing the great Vedic sacrifices such as the ashvamedha", "body_hi": "अश्वमेध जैसे बड़े वैदिक यज्ञों को करने के नियमों का", "id": "c", "isCorrect": false}, {"body": "social and economic life in their times -- trade, crafts and guilds", "body_hi": "अपने समय के सामाजिक और आर्थिक जीवन का, जैसे व्यापार, शिल्प और श्रेणियाँ", "id": "d", "isCorrect": true}]'::jsonb returning concept_group_id;
