update public.questions set options = '[{"body": "A ''ford-maker'' who shows the way across the stream of rebirth", "body_hi": "''घाट बनाने वाला'', जो पुनर्जन्म की धारा पार करने की राह दिखाता है", "id": "a", "isCorrect": true}, {"body": "A lay follower who has taken the twelve minor vows of householders", "body_hi": "एक गृहस्थ अनुयायी जिसने गृहस्थों के लिए निर्धारित बारह लघु व्रत ग्रहण किए हैं", "id": "b", "isCorrect": false}, {"body": "A king who protects the faith", "body_hi": "धर्म की रक्षा करने वाला राजा", "id": "c", "isCorrect": false}, {"body": "A teacher of Vedic ritual", "body_hi": "वैदिक कर्मकांड का आचार्य", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '22c59eea-5337-4f8b-b47a-025a49f5704a' and options = '[{"body": "A ''ford-maker'' who shows the way across the stream of rebirth", "body_hi": "''घाट बनाने वाला'', जो पुनर्जन्म की धारा के पार जाने का मार्ग दिखाता है", "id": "a", "isCorrect": true}, {"body": "A lay follower who has taken the twelve minor vows of householders", "body_hi": "गृहस्थों के बारह लघु व्रत लेने वाला उपासक", "id": "b", "isCorrect": false}, {"body": "A king who protects the faith", "body_hi": "धर्म की रक्षा करने वाला राजा", "id": "c", "isCorrect": false}, {"body": "A teacher of Vedic ritual", "body_hi": "वैदिक कर्मकांड का आचार्य", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "Bribing voters or candidates", "body_hi": "मतदाताओं या उम्मीदवारों को रिश्वत देना", "id": "a", "isCorrect": false}, {"body": "Seeking votes by appealing to the candidate''s religion or caste", "body_hi": "उम्मीदवार के धर्म या जाति के नाम पर अपील करके मतदाताओं से मत माँगना", "id": "b", "isCorrect": false}, {"body": "Incurring expenditure beyond the prescribed limit", "body_hi": "निर्धारित सीमा से अधिक व्यय करना", "id": "c", "isCorrect": false}, {"body": "Holding a public meeting within 48 hours of the close of poll", "body_hi": "मतदान समाप्ति से पहले के 48 घंटों में सार्वजनिक सभा करना", "id": "d", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '828c96a9-a784-4b5d-bfa0-44da9308803e' and options = '[{"body": "Bribing voters or candidates", "body_hi": "मतदाताओं या उम्मीदवारों को रिश्वत देना", "id": "a", "isCorrect": false}, {"body": "Seeking votes by appealing to the candidate''s religion or caste", "body_hi": "उम्मीदवार के धर्म या जाति के आधार पर मत माँगना", "id": "b", "isCorrect": false}, {"body": "Incurring expenditure beyond the prescribed limit", "body_hi": "निर्धारित सीमा से अधिक व्यय करना", "id": "c", "isCorrect": false}, {"body": "Holding a public meeting within 48 hours of the close of poll", "body_hi": "मतदान समाप्त होने से पहले के 48 घंटों में सार्वजनिक सभा करना", "id": "d", "isCorrect": true}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "switching off all of its engines, so that it simply sinks to the depth it needs", "body_hi": "अपने सभी इंजन बंद करके, ताकि वह अपने-आप उतनी गहराई तक डूब जाए जितनी उसे चाहिए", "id": "a", "isCorrect": false}, {"body": "pumping extra compressed air into its tanks, which pushes the hull down", "body_hi": "अपनी टंकियों में अतिरिक्त संपीडित हवा भरकर, जो पनडुब्बी के ढाँचे को नीचे की ओर धकेलती है", "id": "b", "isCorrect": false}, {"body": "letting sea water into its ballast tanks to make it heavier for its size", "body_hi": "अपनी गिट्टी टंकियों में समुद्री पानी भरकर, ताकि वह आकार के अनुपात में भारी हो जाए", "id": "c", "isCorrect": true}, {"body": "folding its fins so that the water around it pushes it under", "body_hi": "अपने पंख मोड़कर, ताकि आसपास का पानी उसे नीचे धकेल दे", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '671d1cca-dfc4-4aa0-b49c-8b66e181bc64' and options = '[{"body": "switching off all of its engines, so that it simply sinks to the depth it needs", "body_hi": "अपने इंजन बंद करके, ताकि वह अपने आप आवश्यक गहराई तक डूब जाए", "id": "a", "isCorrect": false}, {"body": "pumping extra compressed air into its tanks, which pushes the hull down", "body_hi": "अपनी टंकियों में अतिरिक्त संपीडित हवा भरकर, जो पतवार को नीचे धकेलती है", "id": "b", "isCorrect": false}, {"body": "letting sea water into its ballast tanks to make it heavier for its size", "body_hi": "अपनी गिट्टी टंकियों (बैलास्ट टैंक) में समुद्री पानी भरकर, ताकि वह अपने आकार के अनुपात में भारी हो जाए", "id": "c", "isCorrect": true}, {"body": "folding its fins so that the water around it pushes it under", "body_hi": "अपने पंख मोड़कर, ताकि आसपास का पानी उसे नीचे धकेल दे", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "The Sudarshana lake had been built by Ashoka himself, to irrigate the dry lands of Saurashtra", "body_hi": "सुदर्शन झील का निर्माण स्वयं अशोक ने सौराष्ट्र की शुष्क भूमि की सिंचाई के उद्देश्य से करवाया था", "id": "a", "isCorrect": false}, {"body": "A ruler of foreign origin used long, polished Sanskrit for royal records before the Guptas", "body_hi": "विदेशी मूल के एक शासक ने गुप्तों से पहले ही राजकीय अभिलेखों में लंबी, परिष्कृत संस्कृत अपनाई", "id": "b", "isCorrect": true}, {"body": "The Shakas had by then given up their rule in western India", "body_hi": "शकों ने तब तक पश्चिमी भारत में अपना शासन छोड़ दिया था", "id": "c", "isCorrect": false}, {"body": "Saurashtra had passed under the rule of the Satavahanas by the middle of the second century CE", "body_hi": "ईसा की दूसरी सदी के मध्य तक सौराष्ट्र सातवाहन शासकों के अधीन आ चुका था", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '0dfb8f7c-0d6a-4c81-ac66-091f67c23ed9' and options = '[{"body": "The Sudarshana lake had been built by Ashoka himself, to irrigate the dry lands of Saurashtra", "body_hi": "सुदर्शन झील स्वयं अशोक ने सौराष्ट्र की सूखी भूमि की सिंचाई के लिए बनवाई थी", "id": "a", "isCorrect": false}, {"body": "A ruler of foreign origin used long, polished Sanskrit for royal records before the Guptas", "body_hi": "विदेशी मूल के एक शासक ने गुप्तों से पहले राजकीय अभिलेखों के लिए लंबी, परिष्कृत संस्कृत का उपयोग किया", "id": "b", "isCorrect": true}, {"body": "The Shakas had by then given up their rule in western India", "body_hi": "शकों ने तब तक पश्चिमी भारत में अपना शासन छोड़ दिया था", "id": "c", "isCorrect": false}, {"body": "Saurashtra had passed under the rule of the Satavahanas by the middle of the second century CE", "body_hi": "दूसरी सदी ई. के मध्य तक सौराष्ट्र सातवाहनों के शासन में आ चुका था", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "is sung at a fast tempo throughout, with rapid ornamental runs (taans) in every section", "body_hi": "आरंभ से अंत तक तीव्र गति में गाया जाता है, और इसके हर खंड में तेज़ अलंकारिक तानें होती हैं", "id": "a", "isCorrect": false}, {"body": "is a light, romantic form meant for the courtesans'' salons of Lucknow", "body_hi": "लखनऊ की महफ़िलों के लिए बना एक हल्का, शृंगारिक रूप है", "id": "b", "isCorrect": false}, {"body": "is a devotional song of the Sufis, sung by a chorus at dargahs", "body_hi": "सूफ़ियों का एक भक्ति-गीत है, जिसे दरगाहों पर एक समूह (कोरस) द्वारा गाया जाता है", "id": "c", "isCorrect": false}, {"body": "keeps to strict, solemn forms with little ornament, often praising gods or kings", "body_hi": "कम अलंकरण वाले कठोर, गंभीर रूपों में बँधा है, और प्रायः देवों या राजाओं की स्तुति करता है", "id": "d", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '4e2fc452-e01e-481a-a6d8-9b266c4f2918' and options = '[{"body": "is sung at a fast tempo throughout, with rapid ornamental runs (taans) in every section", "body_hi": "आद्योपांत तीव्र गति में, हर खंड में तेज़ अलंकारिक तानों के साथ गाया जाता है", "id": "a", "isCorrect": false}, {"body": "is a light, romantic form meant for the courtesans'' salons of Lucknow", "body_hi": "लखनऊ की महफ़िलों के लिए बना एक हल्का, शृंगारिक रूप है", "id": "b", "isCorrect": false}, {"body": "is a devotional song of the Sufis, sung by a chorus at dargahs", "body_hi": "सूफ़ियों का भक्ति-गीत है, जो दरगाहों पर समूह में गाया जाता है", "id": "c", "isCorrect": false}, {"body": "keeps to strict, solemn forms with little ornament, often praising gods or kings", "body_hi": "कठोर, गंभीर रूपों का पालन करता है जिनमें अलंकरण कम होता है, प्रायः देवताओं या राजाओं की स्तुति में", "id": "d", "isCorrect": true}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "It shows a royal woman granting land in her own right, though the texts did not expect women to hold land", "body_hi": "इसमें एक राजवंशी स्त्री अपने अधिकार से भूमि दान करती है, जबकि ग्रंथ स्त्रियों से भूमि रखने की अपेक्षा नहीं करते थे", "id": "a", "isCorrect": true}, {"body": "It is the earliest inscription found anywhere in the subcontinent that uses the Brahmi script for its text", "body_hi": "यह उपमहाद्वीप में कहीं भी मिला सबसे पुराना अभिलेख है जिसके पाठ में ब्राह्मी लिपि प्रयुक्त है", "id": "b", "isCorrect": false}, {"body": "It proves that the Vakataka kingdom had already been annexed and was now ruled directly by the Gupta emperors", "body_hi": "यह सिद्ध करता है कि वाकाटक राज्य का गुप्त साम्राज्य में विलय हो चुका था और अब उस पर गुप्त सम्राट सीधे शासन करते थे", "id": "c", "isCorrect": false}, {"body": "It records the first-ever grant of land made to a Buddhist monastery by any ruler in India", "body_hi": "यह भारत में किसी भी शासक द्वारा किसी बौद्ध विहार को दिए गए सबसे पहले भूमि-अनुदान को दर्ज करता है", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '2fc65d92-bf8e-436d-be21-55591c8c7387' and options = '[{"body": "It shows a royal woman granting land in her own right, though the texts did not expect women to hold land", "body_hi": "यह एक राजपरिवार की महिला को अपने अधिकार से भूमि दान करते दिखाता है, यद्यपि ग्रंथ महिलाओं से भूमि रखने की अपेक्षा नहीं करते थे", "id": "a", "isCorrect": true}, {"body": "It is the earliest inscription found anywhere in the subcontinent that uses the Brahmi script for its text", "body_hi": "यह उपमहाद्वीप में कहीं भी मिला सबसे पुराना अभिलेख है जिसके पाठ में ब्राह्मी लिपि प्रयुक्त है", "id": "b", "isCorrect": false}, {"body": "It proves that the Vakataka kingdom had already been annexed and was now ruled directly by the Gupta emperors", "body_hi": "यह सिद्ध करता है कि वाकाटक राज्य का विलय हो चुका था और अब उस पर गुप्त सम्राट सीधे शासन करते थे", "id": "c", "isCorrect": false}, {"body": "It records the first-ever grant of land made to a Buddhist monastery by any ruler in India", "body_hi": "यह भारत में किसी भी शासक द्वारा किसी बौद्ध विहार को दिए गए भूमि के पहले अनुदान को दर्ज करता है", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
update public.questions set options = '[{"body": "making it into polyblend, a powder mixed with bitumen to lay roads", "body_hi": "उसे पॉलीब्लेंड चूर्ण बनाकर, जिसे सड़क बिछाने में बिटुमेन से मिलाते हैं", "id": "a", "isCorrect": true}, {"body": "burning it in large power plants to generate electricity for the city", "body_hi": "उसे बड़े-बड़े बिजलीघरों में जलाकर पूरे नगर के लिए बिजली का उत्पादन करके", "id": "b", "isCorrect": false}, {"body": "converting it into diesel fuel by heating it without oxygen", "body_hi": "उसे ऑक्सीजन की अनुपस्थिति में गर्म करके डीज़ल ईंधन में परिवर्तित करके", "id": "c", "isCorrect": false}, {"body": "compressing it into blocks for building low-cost houses", "body_hi": "उसे दबाकर कम लागत वाले घरों के लिए ईंटें बनाकर", "id": "d", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and id = '83167f22-fd0e-4354-bf30-96c1b9259f11' and options = '[{"body": "making it into polyblend, a powder mixed with bitumen to lay roads", "body_hi": "उसे पॉलीब्लेंड नामक चूर्ण में बदलकर, जिसे सड़कें बनाने के लिए बिटुमेन में मिलाया जाता है", "id": "a", "isCorrect": true}, {"body": "burning it in large power plants to generate electricity for the city", "body_hi": "उसे बड़े बिजलीघरों में जलाकर नगर के लिए बिजली बनाकर", "id": "b", "isCorrect": false}, {"body": "converting it into diesel fuel by heating it without oxygen", "body_hi": "उसे बिना ऑक्सीजन के गर्म करके डीज़ल ईंधन में बदलकर", "id": "c", "isCorrect": false}, {"body": "compressing it into blocks for building low-cost houses", "body_hi": "उसे दबाकर कम लागत वाले घरों के लिए ईंटें बनाकर", "id": "d", "isCorrect": false}]'::jsonb returning concept_group_id;
