update public.questions set question_data = '{"closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "craft": "precision", "fixed_option_order": true, "statements": ["It was agreed upon while Mahatma Gandhi was on a fast in Yerwada jail against separate electorates for the Depressed Classes.", "It abolished reservation of seats for the Depressed Classes in provincial legislatures.", "The number of seats reserved for the Depressed Classes in provincial legislatures under the Pact was higher than what had been proposed in the Communal Award."], "statements_hi": ["यह तब तय हुआ जब महात्मा गांधी दलित वर्गों के पृथक निर्वाचन के विरुद्ध यरवदा जेल में अनशन पर थे।", "इसने प्रांतीय विधानमंडलों में दलित वर्गों के लिए सीटों का आरक्षण समाप्त कर दिया।", "इस समझौते के तहत प्रांतीय विधानमंडलों में दलित वर्गों के लिए आरक्षित सीटों की संख्या सांप्रदायिक पंचाट में प्रस्तावित संख्या से अधिक थी।"]}'::jsonb, explanation = 'Statement 1 is correct: the Poona Pact (24 September 1932) was reached to end the fast that Mahatma Gandhi had begun in Yerwada Central Jail against separate electorates for the Depressed Classes. Dr. B. R. Ambedkar signed it for the Depressed Classes and Madan Mohan Malaviya for the caste Hindus; Gandhi himself was not a signatory, though he accepted the Pact and broke his fast once the British government approved it. Statement 2 is incorrect: the Pact did not abolish reservation -- it replaced the Communal Award''s system of SEPARATE electorates for the Depressed Classes with RESERVED seats within a single joint electorate; reservation itself continued. Statement 3 is correct: to compensate for giving up separate electorates, the Pact actually increased the number of reserved seats in provincial legislatures above what the Communal Award had originally proposed.', explanation_hi = 'कथन 1 सही है: पूना समझौता (24 सितंबर 1932) उस अनशन को समाप्त कराने के लिए हुआ जो महात्मा गांधी ने दलित वर्गों के पृथक निर्वाचन के विरुद्ध यरवदा केंद्रीय जेल में शुरू किया था। दलित वर्गों की ओर से डॉ. बी.आर. आंबेडकर और सवर्ण हिंदुओं की ओर से मदन मोहन मालवीय ने इस पर हस्ताक्षर किए; गांधी स्वयं हस्ताक्षरकर्ता नहीं थे, यद्यपि उन्होंने समझौते को स्वीकार किया और ब्रिटिश सरकार की स्वीकृति मिलने पर अपना अनशन तोड़ा। कथन 2 गलत है: समझौते ने आरक्षण समाप्त नहीं किया; इसने सांप्रदायिक पंचाट की दलित वर्गों के लिए पृथक निर्वाचन की व्यवस्था की जगह एक संयुक्त निर्वाचन के भीतर आरक्षित सीटें रखीं, और आरक्षण बना रहा। कथन 3 सही है: पृथक निर्वाचन छोड़ने की भरपाई के लिए समझौते ने प्रांतीय विधानमंडलों में आरक्षित सीटों की संख्या सांप्रदायिक पंचाट में प्रस्तावित संख्या से बढ़ा दी।', updated_at = now() where exam_category = 'upsc' and id = '6e764bab-74e4-4b64-b1a1-e7c6e036a87b' and question_data = '{"closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "craft": "precision", "fixed_option_order": true, "statements": ["It was signed between Mahatma Gandhi and Dr. B. R. Ambedkar.", "It abolished reservation of seats for the Depressed Classes in provincial legislatures.", "The number of seats reserved for the Depressed Classes in provincial legislatures under the Pact was higher than what had been proposed in the Communal Award."], "statements_hi": ["यह महात्मा गांधी और डॉ. बी.आर. आंबेडकर के बीच हुआ।", "इसने प्रांतीय विधानमंडलों में दलित वर्गों के लिए सीटों का आरक्षण समाप्त कर दिया।", "इस समझौते के तहत प्रांतीय विधानमंडलों में दलित वर्गों के लिए आरक्षित सीटों की संख्या सांप्रदायिक पंचाट में प्रस्तावित संख्या से अधिक थी।"]}'::jsonb returning concept_group_id;
